def _apply_is_operations(self, filter_: dict) -> dict:
    """ Transform IS operations to match the expected format where
    $or/$and operators are at the top level with property-specific
    conditions inside.

    Transforms:
      {"property": {"$or": [{"$exists": False}, {"$eq": None}]}}
    into:
      {"$or": [{"property": {"$exists": False}}, {"property": {"$eq": None}}]}

    And similarly for $and operations with IS KNOWN.
    """

    def check_is_operation(prop, expr):
        # Check if this is an IS operation result: property -> {"$or"/"$and": [{conditions without property}]}
        if not isinstance(expr, dict):
            return False
        if "$or" not in expr and "$and" not in expr:
            return False
        op_key = "$or" if "$or" in expr else "$and"
        op_value = expr[op_key]
        if not isinstance(op_value, list):
            return False
        # Check that all items in the list are simple conditions (no property references)
        for item in op_value:
            if not isinstance(item, dict):
                return False
            # Should contain only $exists or $eq/$ne operators without property names
            if not (("$exists" in item and len(item) == 1) or 
                    (("$eq" in item or "$ne" in item) and len(item) == 1)):
                return False
        return True

    def apply_is_operation(subdict, prop, expr):
        # Extract the operator and its operands
        op_key = "$or" if "$or" in expr else "$and"
        op_value = expr[op_key]

        # Transform each operand to include the property name
        new_operands = []
        for item in op_value:
            new_item = {}
            for k, v in item.items():
                new_item[k] = v
            # Add the property name to each condition
            new_item_with_prop = {prop: new_item}
            new_operands.append(new_item_with_prop)

        # Return the transformed expression
        return {op_key: new_operands}

    return recursive_postprocessing(filter_, check_is_operation, apply_is_operation)

