def _apply_is_operations(self, filter_: dict) -> dict:
    """ Transform IS operations to match the expected format where
    $or/$and operators are at the top level with property-specific
    conditions inside.

    Handles both direct IS operations and those wrapped in $not:

    Direct:
      {"property": {"$or": [{"$exists": False}, {"$eq": None}]}}
    into:
      {"$or": [{"property": {"$exists": False}}, {"property": {"$eq": None}}]}

      {"property": {"$and": [{"$exists": True}, {"$ne": None}]}}
    into:
      {"$and": [{"property": {"$exists": True}}, {"property": {"$ne": None}}]}

    With $not:
      {"property": {"$not": {"$or": [{"$exists": False}, {"$eq": None}]}}}
    into:
      {"$and": [{"property": {"$exists": True}}, {"property": {"$ne": None}}]}

      {"property": {"$not": {"$and": [{"$exists": True}, {"$ne": None}]}}}
    into:
      {"$or": [{"property": {"$exists": False}}, {"property": {"$eq": None}}]}
    """

    def check_is_operation(prop, expr):
        # Check if this is an IS operation result: property -> {"$or"/"$and": [{conditions without property}]}
        # Or a $not wrapped IS operation: property -> {"$not": {"$or"/"$and": [{conditions without property}]}}
        if not isinstance(expr, dict):
            return False

        # Direct IS operation case
        if "$or" in expr or "$and" in expr:
            if "$or" in expr and "$and" in expr:
                return False  # Can't have both
            op_key = "$or" if "$or" in expr else "$and"
            op_value = expr[op_key]
            if not isinstance(op_value, list):
                return False
            # Check that all items in the list are simple conditions (no property references)
            for item in op_value:
                if not isinstance(item, dict):
                    return False
                # Should contain only $exists or $eq/$ne operators without property names
                if not (("$exists" in item and len(item) == 1) or 
                        (("$eq" in item or "$ne" in item) and len(item) == 1)):
                    return False
            return True

        # $not wrapped IS operation case
        if "$not" in expr and len(expr) == 1:
            not_content = expr["$not"]
            if not isinstance(not_content, dict):
                return False
            if "$or" not in not_content and "$and" not in not_content:
                return False
            if "$or" in not_content and "$and" in not_content:
                return False  # Can't have both
            op_key = "$or" if "$or" in not_content else "$and"
            op_value = not_content[op_key]
            if not isinstance(op_value, list):
                return False
            # Check that all items in the list are simple conditions (no property references)
            for item in op_value:
                if not isinstance(item, dict):
                    return False
                # Should contain only $exists or $eq/$ne operators without property names
                if not (("$exists" in item and len(item) == 1) or 
                        (("$eq" in item or "$ne" in item) and len(item) == 1)):
                    return False
            return True

        return False

    def apply_is_operation(subdict, prop, expr):
        # Handle $not wrapped case
        if "$not" in expr and len(expr) == 1:
            not_content = expr["$not"]
            # Determine the operator inside the $not
            op_key = "$or" if "$or" in not_content else "$and"
            op_value = not_content[op_key]

            # Transform each operand to include the property name
            new_operands = []
            for item in op_value:
                new_item = {}
                for k, v in item.items():
                    new_item[k] = v
                # Add the property name to each condition
                new_item_with_prop = {prop: new_item}
                new_operands.append(new_item_with_prop)

            # Apply De Morgan's law: NOT (A OR B) = (NOT A) AND (NOT B)
            #                   NOT (A AND B) = (NOT A) OR (NOT B)
            # For our specific case:
            # NOT ({$exists: False} OR {$eq: None}) = {$exists: True} AND {$ne: None}
            # NOT ({$exists: True} AND {$ne: None}) = {$exists: False} OR {$eq: None}
            if op_key == "$or":
                # NOT (OR) = AND
                new_op_key = "$and"
                # Negate the conditions: $exists:false -> $exists:true, $eq:null -> $ne:null
                negated_operands = []
                for operand in new_operands:
                    negated_operand = {}
                    for k, v in operand.items():
                        if k == "$exists":
                            negated_operand[k] = not v  # False -> True, True -> False
                        elif k == "$eq":
                            negated_operand["$ne"] = v  # $eq:null -> $ne:null
                        elif k == "$ne":
                            negated_operand["$eq"] = v  # $ne:null -> $eq:null
                        else:
                            negated_operand[k] = v
                    negated_operands.append(negated_operand)
                return {new_op_key: negated_operands}
            else:  # op_key == "$and"
                # NOT (AND) = OR
                new_op_key = "$or"
                # Negate the conditions: $exists:true -> $exists:false, $ne:null -> $eq:null
                negated_operands = []
                for operand in new_operands:
                    negated_operand = {}
                    for k, v in operand.items():
                        if k == "$exists":
                            negated_operand[k] = not v  # True -> False, False -> True
                        elif k == "$ne":
                            negated_operand["$eq"] = v  # $ne:null -> $eq:null
                        elif k == "$eq":
                            negated_operand["$ne"] = v  # $eq:null -> $ne:null
                        else:
                            negated_operand[k] = v
                    negated_operands.append(negated_operand)
                return {new_op_key: negated_operands}

        # Direct IS operation case (no $not wrapper)
        op_key = "$or" if "$or" in expr else "$and"
        op_value = expr[op_key]

        # Transform each operand to include the property name
        new_operands = []
        for item in op_value:
            new_item = {}
            for k, v in item.items():
                new_item[k] = v
            # Add the property name to each condition
            new_item_with_prop = {prop: new_item}
            new_operands.append(new_item_with_prop)

        # Return the transformed expression
        return {op_key: new_operands}

    return recursive_postprocessing(filter_, check_is_operation, apply_is_operation)

